<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {screens,type Console,type Row} from '../console';
import Icon from './Icon.vue';
const props=defineProps<{c:Console}>();const query=ref(''),status=ref('all'),application=ref('all');
const screen=computed(()=>screens[props.c.s.page]);
watch(()=>props.c.s.page,()=>{query.value='';status.value='all';application.value='all';});
const filtered=computed(()=>props.c.s.rows.filter(r=>{const match=Object.values(r).some(v=>String(v??'').toLowerCase().includes(query.value.trim().toLowerCase()));const enabled='active'in r?r.active:r.enabled;return match&&(status.value==='all'||enabled===(status.value==='enabled'))&&(application.value==='all'||r.systemId===Number(application.value));}));
const passwordDialog=ref<HTMLDialogElement|null>(null),passwordUser=ref<Row|null>(null),newPassword=ref('');
/** 单独设置凭证，不把导入员工自动启用。 */
function setPassword(row:Row){passwordUser.value=row;newPassword.value='';props.c.s.notice='';passwordDialog.value?.showModal();}
async function savePassword(){await props.c.run(async()=>{await props.c.api(`/api/users/${passwordUser.value?.id}/password`,'PUT',{password:newPassword.value});passwordDialog.value?.close();newPassword.value='';props.c.message('密码已设置；账号启用状态保持原值');});}
function edit(row:Row|null){props.c.s.editing=row;props.c.s.editor=true;}
</script>
<template><section class="panel resource-panel"><div class="toolbar"><div class="search-field"><Icon name="search"/><input v-model="query" :placeholder="c.s.page==='users'?'搜索本页姓名、登录名…':'搜索名称、编码…'" aria-label="搜索当前列表"><kbd>/</kbd></div><div class="toolbar-filters"><select v-if="c.s.page!=='departments'" v-model="status" aria-label="状态筛选"><option value="all">全部状态</option><option value="enabled">已启用</option><option value="disabled">已停用</option></select><select v-if="['permissions','resources'].includes(c.s.page)" v-model="application" aria-label="应用筛选"><option value="all">全部应用</option><option v-for="app in c.s.systems" :key="app.id" :value="app.id">{{app.name}}</option></select><button class="icon-button" aria-label="刷新列表" :disabled="c.s.busy" @click="c.run(c.refresh)"><Icon name="refresh"/></button></div></div><div class="table-scroll"><table><thead><tr><th v-for="[key,label] in screen.columns" :key="key">{{label}}</th><th class="align-right">操作</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id"><td v-for="([key],index) in screen.columns" :key="key"><div v-if="index===0" class="identity-cell"><span :class="['row-avatar',c.s.page==='users'?'':'square']">{{(row.displayName||row.name||'?').slice(0,1)}}</span><div><strong>{{c.label(key,row[key])}}</strong><small>{{c.s.page==='users'?row.username:'#'+String(row.id).padStart(3,'0')}}</small><details v-if="c.s.page==='users'&&row.companyName" class="profile-details"><summary>来源资料</summary><p>分公司：{{row.companyName}}<br>原部门：{{row.sourceDepartment}}<br>岗位：{{row.jobTitle}}<br>电话：{{row.phone}}</p></details><details v-if="c.s.page==='permissions'&&row.sourceDescription" class="profile-details"><summary>来源说明与授权矩阵</summary><p>{{row.sourceDescription}}</p><p>{{row.sourceGrants}}</p></details></div></div><span v-else-if="['enabled','active'].includes(key)" :class="['badge',row[key]?'green':'neutral']"><i/>{{row[key]?'已启用':'已停用'}}</span><span v-else-if="key==='type'" class="badge neutral">{{c.label(key,row[key])}}</span><span v-else-if="key==='method'" :class="['http-method',String(row[key]).toLowerCase()]">{{row[key]}}</span><code v-else-if="['code','path','baseUrl'].includes(key)">{{c.label(key,row[key])}}</code><span v-else>{{c.label(key,row[key])}}</span></td><td><div class="row-actions"><button :disabled="c.s.busy" @click="edit(row)">编辑</button><button v-if="c.s.page==='users'" :disabled="c.s.busy" @click="setPassword(row)">设置密码</button><button v-if="'enabled'in row||'active'in row" :disabled="c.s.busy" @click="c.status(row)">{{('active'in row?row.active:row.enabled)?'停用':'启用'}}</button><button class="icon-button subtle-danger" :aria-label="'删除'+(row.name||row.displayName)" :disabled="c.s.busy" @click="c.remove(row)"><Icon name="trash" :size="16"/></button></div></td></tr></tbody></table></div><div v-if="!filtered.length" class="empty"><Icon :name="screen.icon" :size="34"/><h3>{{query||status!=='all'||application!=='all'?'没有匹配的结果':'这里还没有'+screen.noun}}</h3><p>{{query||status!=='all'||application!=='all'?'试试调整搜索内容或筛选条件。':'先创建一个'+screen.noun+'，再继续配置访问关系。'}}</p><button v-if="!c.s.rows.length" :disabled="c.s.busy" @click="edit(null)"><Icon name="plus"/>新增{{screen.noun}}</button></div><footer class="table-footer"><span>共 <strong>{{c.s.total}}</strong> 项<span v-if="query||status!=='all'||application!=='all'"> · 本页匹配 {{filtered.length}} 项</span><span v-if="c.s.page==='users'"> · 每页 10 项</span></span><div v-if="c.s.page==='users'" class="pagination"><button class="icon-button" aria-label="上一页" :disabled="c.s.busy||c.s.currentPage===0" @click="c.s.currentPage--;c.run(c.refresh)"><Icon name="chevron" class="rotate" :size="16"/></button><span>{{c.s.currentPage+1}} / {{Math.max(1,Math.ceil(c.s.total/10))}}</span><button class="icon-button" aria-label="下一页" :disabled="c.s.busy||(c.s.currentPage+1)*10>=c.s.total" @click="c.s.currentPage++;c.run(c.refresh)"><Icon name="chevron" :size="16"/></button></div><span v-else class="muted small-text">显示 {{filtered.length}} 项</span></footer></section><dialog ref="passwordDialog" class="editor-dialog password-dialog" aria-labelledby="password-title"><form @submit.prevent="savePassword"><div class="dialog-heading"><h2 id="password-title">设置用户密码</h2><button class="icon-button" type="button" aria-label="关闭设置密码" :disabled="c.s.busy" @click="passwordDialog?.close()"><Icon name="close"/></button></div><p class="muted">为 {{passwordUser?.displayName}}（{{passwordUser?.username}}）设置登录凭证。已有令牌会失效；若账号停用，请完成密码设置后在列表单独启用。</p><label>员工新密码<input v-model="newPassword" aria-label="员工新密码" type="password" autocomplete="new-password" required minlength="8" maxlength="72"><small>至少 8 位，大小写、数字、符号中至少包含三类。</small></label><p v-if="c.s.failure&&c.s.notice" class="inline-error" role="alert">{{c.s.notice}}</p><footer class="dialog-actions"><button type="button" :disabled="c.s.busy" @click="passwordDialog?.close()">取消</button><button class="primary" :disabled="c.s.busy">保存密码</button></footer></form></dialog></template>
